package com.acttub.actingapi.config;
import com.acttub.actingapi.auth.AccessTokenFilter; import org.springframework.boot.web.servlet.FilterRegistrationBean; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain apiSecurity(HttpSecurity http,AccessTokenFilter access)throws Exception{return http.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).httpBasic(h->h.disable()).formLogin(f->f.disable()).addFilterBefore(access,UsernamePasswordAuthenticationFilter.class).build();}@Bean FilterRegistrationBean<AccessTokenFilter> accessTokenFilterRegistration(AccessTokenFilter filter){FilterRegistrationBean<AccessTokenFilter> bean=new FilterRegistrationBean<>(filter);bean.setEnabled(false);return bean;}}
